-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Fogo"
L["rm.era.mage.fire.Description"] = "Fogo do nível 10 ao 60, escolhida quando você tem pontos em Fogo e nenhum em Gelo, ou quando Fogo é sua árvore principal. Ignimpacto (senão Bola de Fogo) abre; Ignimpacto após Presença de Espírito; Calcinar mantém cinco acúmulos de Vulnerabilidade ao Fogo com Calcinar Aprimorado em alvos que vão sobreviver; Impacto de Fogo e Calcinar finalizam; Bola de Fogo preenche. Três ou mais inimigos em combate: Onda de Impacto, Golpe Flamejante, Explosão Arcana, Cone de Frio, Nevasca. Lembretes: Combustão com cinco acúmulos de Calcinar em elites e lutas longas, armadura, Inteligência Arcana, gemas de mana, Barreira de Gelo, Escudo de Mana, Evocação, Contrafeitiço, Remover Maldição Inferior, Bloco de Gelo, Presença de Espírito. Desativado por padrão: intercalar Impacto de Fogo sempre que estiver pronto."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Fogo (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Fogo segundo a Warcraft Tavern, uma alternativa à rotação integrada de Fogo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Combustão é gasta na puxada em elites e chefes em vez de esperar os acúmulos de Calcinar; Ignimpacto abre; Calcinar mantém cinco acúmulos com Calcinar Aprimorado; Bola de Fogo preenche; Impacto de Fogo só em movimento. Grupos de inimigos: Golpe Flamejante primeiro, depois Explosão Arcana, Cone de Frio e Onda de Impacto de perto, Nevasca à distância. Os mesmos lembretes da rotação integrada de Fogo."
L["rm.era.mage.frost.Name"] = "Gélido"
L["rm.era.mage.frost.Description"] = "Gelo do nível 1 ao 60, também para builds de Arcano e o padrão do Mago antes dos talentos. Seta de Gelo (Bola de Fogo antes do nível 4); Nova Congelante quando um monstro chega até você, exceto em chefes de raide; Mísseis Arcanos depois que um monstro chega até você, se você tiver Mísseis Arcanos Aprimorados; Cone de Frio, Explosão Arcana e Nevasca quando três ou mais inimigos estão em combate; Impacto de Fogo em movimento com mana de sobra; Impacto de Fogo e a varinha finalizam monstros comuns quando solo; varinha quando a mana acaba. Lembretes: armadura (Armadura de Gelo solo, Armadura de Mago em grupo, nunca substituindo uma que você escolheu), Inteligência Arcana, conjurar e usar gemas de mana, Barreira de Gelo, Escudo de Mana, Evocação, Contrafeitiço, Remover Maldição Inferior, Bloco de Gelo, Ruptura do Gelo, Poder Arcano e Presença de Espírito. Desativados por padrão: o Golpe Flamejante de Estilhaçar e a Seta de Gelo grau 1 para acumular Calafrio do Inverno. Lampejo, Polimorfia, kiting e escolha de alvo ficam com você."
L["rm.era.mage.frost.icyveins.Name"] = "Gélido, grind em área (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Evolução de nível com Nevasca segundo o guia de grind em área da Icy Veins, escolhida automaticamente quando você joga solo com Nevasca Aprimorada. A partir de dois inimigos em combate: Nova Congelante no grupo de inimigos, Cone de Frio enquanto Nova está em recarga, Nevasca quando nada estiver ao seu lado, Explosão Arcana quando estiverem; Seta de Gelo em um alvo único, Impacto de Fogo e a varinha para finalizar. Escudo de Mana e Barreira de Gelo são ativados antes de cada puxada. Reunir o grupo de inimigos, Lampejo e kiting ficam com você."
L["rm.forever.mage.arcane.Name"] = "Arcano"
L["rm.forever.mage.arcane.Description"] = "Arcano assim que Arcano é sua árvore de talentos principal com 11 pontos e você conhece Impacto Arcano. Puxa com Seta de Gelo quando solo ou Impacto Arcano em grupo; depois Mísseis Arcanos com Salva de Mísseis, Impacto Arcano com Abstração, Ira Arcana com três acúmulos de Impacto Arcano, Impacto Arcano até quatro acúmulos em elites e dois em outros alvos enquanto você puder pagar por ele (a mana fica oculta no Forever), depois Seta de Fogofrio, Seta de Gelo ou Bola de Fogo para buscar Salva de Mísseis, e uma varinha quando solo e você não pode pagar por um feitiço. Sem Ira Arcana (o design mais antigo do beta), Impacto de Fogo gasta os acúmulos. Em movimento: Impacto de Fogo. Três ou mais inimigos lutando com você: Explosão Arcana. Lembretes: Presença de Espírito e Poder Arcano em elites (Poder Arcano não espera mais pela metade da sua mana), além dos lembretes de manutenção do Mago."
L["rm.forever.mage.fire.Name"] = "Fogo"
L["rm.forever.mage.fire.Description"] = "Fogo assim que Fogo é sua árvore de talentos principal com 11 pontos (o nível do Ignimpacto). Puxa com Ignimpacto em elites, senão Seta de Fogofrio ou Bola de Fogo; depois Ignimpacto com três acúmulos de Aquecendo, Lança de Gelo com Dedos Glaciais ou em um alvo congelado (híbridos Fogo/Gélido), Impacto de Fogo sempre que sair do tempo de recarga, Calcinar para manter seus cinco acúmulos de Vulnerabilidade ao Fogo em elites, Seta de Fogofrio (a partir do 40) ou Bola de Fogo, varinha quando solo e você não pode pagar por um feitiço. Em movimento: Impacto de Fogo ou Lança de Gelo. Quatro ou mais inimigos lutando com você: Golpe Flamejante, Onda de Impacto, Explosão Arcana. Calcinar só inicia os acúmulos depois que você tiver Calcinar Aprimorado; um Calcinar a curta distância fica desativado até você ativá-lo. Lembretes: Combustão e Presença de Espírito em elites, além dos lembretes de manutenção do Mago."
L["rm.forever.mage.fire.icyveins.Name"] = "Fogo para evolução de nível (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "A build de Fogo para evolução de nível da Icy Veins sem Calcinar Aprimorado, uma alternativa à rotação integrada de Fogo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Puxa com Ignimpacto, usa Impacto de Fogo para gastar Caminho de Fogo, Calcinar enquanto o monstro se aproxima (a vida do alvo fica oculta no Forever, então os finalizadores para alvos com pouca vida ficam com você), depois Seta de Fogofrio (a partir do 40) ou Bola de Fogo. A mesma AoE, movimento, varinha e lembretes da rotação integrada de Fogo, sem Combustão e Presença de Espírito."
L["rm.forever.mage.frost.Name"] = "Gélido"
L["rm.forever.mage.frost.Description"] = "Gélido do nível 1 ao 60, e o padrão do Mago no Forever antes dos feitiços de talento (Bola de Fogo até Seta de Gelo no nível 4). Puxa com Seta de Gelo; depois Lança de Gelo com Dedos Glaciais ou em um alvo congelado (também enquanto Seta de Gelo ainda está sendo lançada, para cancelar ou agrupar), Cone de Frio com cinco acúmulos de Calafrio do Inverno, Mísseis Arcanos com Salva de Mísseis, Seta de Gelo, e uma varinha quando solo e você não pode pagar por Seta de Gelo. Em movimento: Lança de Gelo, senão Impacto de Fogo. Três ou mais inimigos lutando com você: Cone de Frio; cinco ou mais: Nevasca, ou Explosão Arcana com um monstro em você. A AoE de Golpe Flamejante e Explosão Arcana da Warcraft Tavern está incluída, mas desativada. Lembretes: Inteligência Arcana, armadura (de Gelo ou Gélida quando solo, Armadura de Mago em grupo, nunca substituindo uma que você escolheu), Barreira de Gelo, Contrafeitiço, Remover Maldição Inferior, Nova Congelante quando um monstro chega até você, Ruptura do Gelo. A vida e a mana ficam ocultas dos addons no Forever, então finalizar alvos com pouca vida com Impacto de Fogo, Evocação e Bloco de Gelo são decisões suas; Lampejo, kiting, Polimorfia e gemas de mana também ficam com você."
L["rm.mop.mage.arcane.Name"] = "Recomendada"
L["rm.mop.mage.arcane.Description"] = "Recomendada para Arcano, do nível 10 ao 90 (selecionada na especialização Arcano). Impacto Arcano acumula quatro Cargas Arcanas; com quatro, uma ativação de Mísseis Arcanos! é gasta com Mísseis, e sem ela Barragem Arcana sai assim que sua mana cai abaixo de 90%. Acima de 95% de mana, continua lançando Impacto, que é como o simulador joga. Mísseis nunca fica parado com duas ativações, Barragem é lançada antes que Alterar o Tempo volte, e com dois ou mais inimigos Barragem sai a cada quatro cargas; Cone de Frio e Explosão Arcana quando cinco estiverem perto. Mantém sua bomba de talento ativa, e Impacto de Fogo ou Lança de Gelo em movimento sem Banquisas. Lembretes: Poder Arcano e Alterar o Tempo com quatro cargas e uma ativação, Armadura Gélida (Armadura Derretida antes do nível 54), Inteligência Arcana, Contrafeitiço, Gema de Mana, Imagem Espelhada, Barreira de Gelo, Banquisas, Runa de Poder ou Invocação. Distorção Temporal, Roubar Feitiço e Presença de Espírito vêm desativados; Runa de Poder ainda precisa ser posicionada à mão."
L["rm.mop.mage.arcane.icyveins.Name"] = "Barragem com quatro cargas (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "A regra de Arcano dos guias (Icy Veins, Wowhead, Method, wowtbc.gg), uma alternativa à rotação integrada recomendada de Arcano: com quatro Cargas Arcanas, Mísseis Arcanos se houver uma ativação, senão Barragem Arcana, seja qual for sua mana; Mísseis só com quatro cargas. Todo o resto (Alterar o Tempo, bombas, dano em área, movimento, lembretes) é igual à recomendada, exceto que Poder Arcano é sugerido com quatro cargas sem esperar uma ativação. Desativada por padrão: ative-a e desative a rotação integrada recomendada de Arcano, ou aumente a prioridade desta."
L["rm.mop.mage.fire.Name"] = "Recomendada"
L["rm.mop.mage.fire.Description"] = "Recomendada para Fogo, do nível 10 ao 90 (selecionada na especialização Fogo). Abre com um Ignimpacto lançado normalmente, depois Impacto Infernal (Impacto de Fogo antes do nível 24) transforma Aquecendo em uma ativação de Ignimpacto!, que é lançada na hora, a menos que Combustão esteja prestes a sair do tempo de recarga; depois espera o próximo Aquecendo enquanto você lança Bola de Fogo. Combustão é acionada logo após um Ignimpacto enquanto Incendiar e a queimadura do Ignimpacto estiverem no alvo; o addon não consegue ver o tamanho de Incendiar, então avalie você mesmo um fraco. Mantém sua bomba de talento ativa, espalha com Impacto Infernal quando dois ou mais inimigos lutam com você, Cone de Frio e Explosão Arcana para cinco por perto, Calcinar em movimento. Lembretes: Armadura Derretida, Presença de Espírito, Alterar o Tempo com as duas ativações, Gema de Mana, Inteligência Arcana, Contrafeitiço, Imagem Espelhada, Barreira de Gelo, Banquisas, Invocação ou Runa de Poder. Sopro do Dragão, Distorção Temporal e Roubar Feitiço vêm desativados."
L["rm.mop.mage.fire.icyveins.Name"] = "Segurar Ignimpacto! (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "O jogo de Fogo da Icy Veins, Method e wowtbc.gg, uma alternativa à rotação integrada recomendada de Fogo: uma ativação de Ignimpacto! é segurada até que um Aquecendo se junte a ela, e então lançada junto com sua Bola de Fogo, e gasta sozinha só quando estiver prestes a expirar. Todo o resto é igual à recomendada. Desativada por padrão: ative-a e desative a rotação integrada recomendada de Fogo, ou aumente a prioridade desta."
L["rm.mop.mage.frost.Name"] = "Recomendada"
L["rm.mop.mage.frost.Description"] = "Gelo do nível 10 ao 90 (selecionada na especialização Gelo). Lança de Gelo com dois Dedos Glaciais, Seta de Fogofrio com Congelamento Cerebral, sua bomba de talento, Orbe Congelado, Lança de Gelo com um Dedos Glaciais, Seta de Gelo; a partir do nível 87, uma ativação é segurada para Alterar o Tempo quando faltarem menos de 10 segundos para ele. Com dois ou mais inimigos: Orbe Congelado, Cone de Frio e Explosão Arcana quando estiverem perto, Nevasca quando quatro estiverem parados. Lança de Gelo e Impacto de Fogo em movimento sem Banquisas. Lembretes: Elemental da Água, Congelamento em qualquer coisa que não seja um chefe (posicione-o você mesmo), Veias Gélidas sincronizadas com Alterar o Tempo, Alterar o Tempo com dois Dedos Glaciais durante Veias Gélidas, Armadura Gélida (Armadura Derretida antes do nível 54), Gema de Mana, Inteligência Arcana, Contrafeitiço, Imagem Espelhada, Barreira de Gelo, Banquisas, Invocação ou Runa de Poder. Ruptura do Gelo, Presença de Espírito, Distorção Temporal e Roubar Feitiço vêm desativados."
L["rm.mop.mage.unspecialized.Name"] = "Antes de uma especialização"
L["rm.mop.mage.unspecialized.Description"] = "Para os níveis 1 a 9, e qualquer Mago que ainda não escolheu uma especialização. Seta de Fogofrio, Impacto de Fogo para finalizar um alvo ou em movimento, Lança de Gelo em movimento depois de aprendida, Explosão Arcana quando três ou mais inimigos estiverem ao alcance corpo a corpo. Lembretes: Nova Congelante quando um monstro chega até você, Contrafeitiço, e Armadura Derretida e Inteligência Arcana se você as alcançar. Escolher uma especialização no nível 10 troca para a rotação integrada dessa especialização."
L["rm.retail.mage.arcane.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.mage.arcane.Description"] = "Recomendada para Arcano. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Surto Arcano em combate, Intelecto Arcano fora de combate, Contrafeitiço em um lançamento interrompível, Barreira Prismática sempre que estiver pronta em combate, e sua habilidade racial em combate. Lançamentos inimigos ficam ocultos em combate, então Contrafeitiço só acende onde o jogo os exibe; a vida fica oculta no Retail, então Bloco de Gelo e outros botões de emergência ficam por sua conta. Imagem Espelhada, Alterar Tempo, Lampejo e berloques ficam com você."
L["rm.retail.mage.arcane.guide.Name"] = "Referência (Icy Veins e SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Arcano dos guias. Saraivada Arcana e Abstração ficam ocultas para addons em combate no Midnight (só as Cargas Arcanas continuam visíveis), então ela não pode funcionar lá; a mana fica oculta no Retail, então a Evocação com pouca mana fica com você; leia-a ou duplique-a para experimentar. Puxa com Impacto Arcano. Solfúria: Mísseis Arcanos com Abstração abaixo de 12 acúmulos de Saraivada, Seta Prismática fora de Alma Arcana, Salva Arcana com quatro cargas e 12 acúmulos de Saraivada com Abstração ou 25 acúmulos de Saraivada, ou com Alma Arcana com qualquer número de cargas, Seta Prismática, Orbe Arcano abaixo de três cargas, Pulso Arcano contra três inimigos ou sem cargas, Impacto Arcano. Lançafeitiços (com Feitiçaria Farpada aprendida): Seta Prismática, Orbe em grupos de inimigos, Salva com 20 acúmulos de Saraivada (só com quatro cargas contra dois ou mais inimigos), Mísseis com Abstração abaixo de 15 acúmulos de Saraivada, Orbe e Pulso abaixo de três cargas (sem Pulso durante Surto Arcano), Impacto Arcano. Salva Arcana quando Impacto não puder ser lançado. Lembretes: Surto Arcano, Toque dos Magos depois de uma Salva ou Seta Prismática durante Surto ou bem antes dele, Presença de Espírito sem cargas depois de uma Salva, além dos lembretes da rotação integrada do Assistente de Combate."
L["rm.retail.mage.fire.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.mage.fire.Description"] = "Recomendada para Fogo. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Combustão em combate, Intelecto Arcano fora de combate, Contrafeitiço em um lançamento interrompível, Barreira Fulgurante sempre que estiver pronta em combate, e sua habilidade racial em combate. Lançamentos inimigos ficam ocultos em combate, então Contrafeitiço só acende onde o jogo os exibe; a vida fica oculta no Retail, então Bloco de Gelo e outros botões de emergência ficam por sua conta."
L["rm.retail.mage.fire.guide.Name"] = "Referência (Icy Veins, Wowhead e SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Fogo dos guias. Embalo de Fogo, Aquecendo, Piroclasma e as cargas de Impacto de Fogo ficam ocultos em combate no Midnight, então ela não pode funcionar lá. Impacto de Fogo enquanto um lançamento termina, para transformar Aquecendo em Embalo de Fogo; puxa com Ignimpacto. Ignimpacto (Golpe Flamejante contra quatro ou mais inimigos) com Hipertermia, Meteoro, Ignimpacto com Embalo de Fogo, Impacto de Fogo com Aquecendo durante Combustão, Ignimpacto com Piroclasma, Calcinar com Calor Fulgurante ou em movimento, Impacto de Fogo com Aquecendo, depois Seta de Fogofrio ou Bola de Fogo. Lembretes: Combustão quando um lançamento completo estiver terminando, Barreira Fulgurante e os lembretes utilitários. Esperar por Incendiário e sincronizar Meteoro com Combustão ficam com você."
L["rm.retail.mage.frost.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.mage.frost.Description"] = "Recomendada para Gélido. Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, lembretes do que o Assistente de Combate deixa por sua conta: Evocar Elemental da Água quando você tem o talento e nenhum elemental, Intelecto Arcano fora de combate, Contrafeitiço em um lançamento interrompível, Barreira de Gelo sempre que estiver pronta em combate, e sua habilidade racial em combate. Lançamentos inimigos ficam ocultos em combate, então Contrafeitiço só acende onde o jogo os exibe; a vida fica oculta no Retail, então Bloco de Gelo e outros botões de emergência ficam por sua conta."
L["rm.retail.mage.frost.guide.Name"] = "Referência (Icy Veins e SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Apenas referência, desativada por padrão: a prioridade de Gélido dos guias para cada árvore de talentos heroicos. Ativações, acúmulos de Congelamento e tempos de recarga ficam ocultos em combate no Midnight, então ela não pode funcionar lá. Puxa com Seta de Fogofrio ou Seta de Gelo. Fogofrio (com Seta de Fogofrio aprendida): Punhal Glacial quando pronto, Chuva de Cometas contra um ou dois inimigos, Ímpeto com Congelamento Cerebral sem Caos Térmico, Lança de Gelo com dois Dedos Glaciais, Raio de Gelo, Orbe Congelado, Nevasca com Chuva Congelante contra três inimigos, Lança de Gelo com Dedos Glaciais junto com Caos Térmico ou com doze acúmulos de Congelamento, Ímpeto, Nova de Gelo ou Cone de Frio contra cinco, depois Punhal Glacial ou Seta de Fogofrio. Lançafeitiços: Chuva de Cometas, Ímpeto com Congelamento Cerebral, Lança de Gelo com dois Dedos, Orbe Congelado, Punhal Glacial quando pronto, Nevasca com Chuva Congelante, Lança de Gelo com Dedos Glaciais ou seis acúmulos de Congelamento, Raio de Gelo, Ímpeto, Nova de Gelo ou Cone de Frio contra quatro, Nevasca contra sete, depois Punhal Glacial ou Seta de Gelo. Lança de Gelo em movimento. Lembretes: Evocar Elemental da Água, Barreira de Gelo e os lembretes utilitários."
L["rm.retail.mage.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.mage.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Mago). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Mago compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.sod.mage.arcane.Name"] = "Arcano (SoD)"
L["rm.sod.mage.arcane.Description"] = "Dano de Arcano da Temporada da Descoberta, escolhida quando Arcano é sua árvore principal e Impacto Arcano está gravado. Mísseis Arcanos com Salva de Mísseis; Salva Arcana com quatro acúmulos de Impacto Arcano; Seta Incendiária quando for seguro, nunca com quatro ou mais acúmulos de Seta Incendiária; Chama Viva assim que sair do tempo de recarga; Impacto Arcano preenche. Salva Arcana e Impacto de Fogo em movimento; Chama Viva e Explosão Arcana em grupos de inimigos. Lembretes: Poder Arcano em elites e lutas longas, Presença de Espírito com Poder Arcano ou em movimento, Veias Gélidas, Ruptura do Gelo e os demais lembretes do Mago."
L["rm.sod.mage.fire.Name"] = "Fogo (SoD)"
L["rm.sod.mage.fire.Description"] = "Fogo da Temporada da Descoberta do nível 1 ao 60, e o padrão do Mago lá. Usa as runas que você gravou: Ignimpacto com Embalo de Fogo na hora; Bomba Viva mantida em alvos que vão sobreviver; Calcinar com Calcinar Aprimorado enquanto Vulnerabilidade ao Fogo estiver abaixo de dois acúmulos ou prestes a expirar; Chama Viva assim que sair do tempo de recarga; Seta Incendiária com cinco acúmulos de Vulnerabilidade ao Fogo, nunca com quatro ou mais acúmulos de Seta Incendiária (o quinto mata você); Seta de Fogofrio, senão Bola de Fogo. Bomba Viva, Chama Viva e Impacto de Fogo em movimento; Chama Viva, Bomba Viva, Onda de Impacto, Cone de Frio, Golpe Flamejante e Nevasca em grupos de inimigos. Lembretes: Impacto de Fogo com Superaquecimento, Combustão, Veias Gélidas e Ruptura do Gelo, Armadura Derretida ou outra armadura, Inteligência Arcana, gemas de mana, Barreira de Gelo, Escudo de Mana, Evocação, Contrafeitiço, remoção de maldições, Bloco de Gelo. Espalhar Bomba Viva por vários alvos fica com você."
L["rm.sod.mage.frost.Name"] = "Gélido (SoD)"
L["rm.sod.mage.frost.Description"] = "Gelo da Temporada da Descoberta a partir do nível 10, escolhida quando Gelo é sua árvore principal. Dedos Glaciais vai para Lança de Gelo com três ou mais dos seus acúmulos de Cobrir com Gelo, senão para Congelamento Profundo; Seta Incendiária com uma ativação de Congelamento Cerebral e, nos demais casos, quando for seguro, nunca com quatro ou mais acúmulos de Seta Incendiária; Bomba Viva e Chama Viva quando gravadas; Seta de Gelo Mágico, senão Seta de Fogofrio, senão Seta de Gelo. Lança de Gelo, Orbe Congelado, Bomba Viva e Impacto de Fogo em movimento; Orbe Congelado, Chama Viva, Bomba Viva, Nevasca e Cone de Frio em grupos de inimigos. Lembretes: Orbe Congelado, Veias Gélidas, Ruptura do Gelo, armadura, gemas de mana e os demais lembretes do Mago. Enfileirar um feitiço enquanto uma seta atinge o alvo fica com você."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Gélido, runas de Fogo (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "A build de Gelo da Fase 4 da Warcraft Tavern com runas de Fogo, uma alternativa à rotação integrada de Gelo da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Ignimpacto abre; Ignimpacto com Embalo de Fogo; Bomba Viva mantida; Calcinar até cinco acúmulos com Calcinar Aprimorado; Seta Incendiária só com uma ativação de Congelamento Cerebral e nunca com quatro ou mais acúmulos de Seta Incendiária; Seta de Fogofrio preenche. Bomba Viva e Impacto de Fogo em movimento; Bomba Viva, Cone de Frio e Nevasca em grupos de inimigos. Lembretes: Impacto de Fogo com Superaquecimento, Orbe Congelado durante Veias Gélidas, Veias Gélidas, Ruptura do Gelo e os demais lembretes do Mago."
L["rm.sod.mage.healer.Name"] = "Curador (SoD)"
L["rm.sod.mage.healer.Description"] = "Cura de Mago da Temporada da Descoberta, escolhida quando Regeneração ou Regeneração em Massa está gravada. Com um alvo amigável: Retroceder Tempo e Preservação Cronostática abaixo de metade da vida, Regeneração quando seu Foco Temporal estiver ausente, Regeneração em Massa, Anomalia Temporal. Com um alvo inimigo, dano que cura seus focos: Seta de Gelo Mágico para curadores de Gelo, senão Mísseis Arcanos com Salva de Mísseis, Salva Arcana com dois acúmulos de Impacto Arcano, Seta Incendiária quando for seguro (nunca com quatro ou mais acúmulos de Seta Incendiária) e Impacto Arcano. Lembretes: Poder Arcano, Presença de Espírito, Orbe Congelado e os demais lembretes do Mago. Desativados por padrão: Explosão Arcana em grupos de inimigos, e Lança de Gelo e Congelamento Profundo para curadores de Gelo. Enquanto você canaliza Regeneração em Massa, o próximo feitiço já aparece, para que você possa cancelá-la na hora (a cura direta dela é pequena). A escolha de quem curar fica com você."
L["rm.tbc.mage.arcane.Name"] = "Arcano"
L["rm.tbc.mage.arcane.Description"] = "Arcano, escolhida quando Arcano é sua árvore de talentos principal. Antes do nível 64: Mísseis Arcanos, com Seta de Gelo quando a mana fica baixa. A partir do 64: Impacto Arcano durante a queima (Poder Arcano, Sede de Sangue ou mana acima de 35%), caso contrário três acúmulos de Impacto Arcano e Seta de Gelo até que estejam prestes a expirar. Explosão Arcana e Cone de Frio para três ou mais inimigos. Os lembretes incluem Poder Arcano, Presença de Espírito, gema de mana e Evocação."
L["rm.tbc.mage.fire.icyveins.Name"] = "Fogo (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Fogo segundo a Icy Veins, escolhida quando Fogo é sua árvore de talentos principal. Ignimpacto abre o combate depois de aprendido, Calcinar Aprimorado mantém cinco acúmulos de Vulnerabilidade ao Fogo, Bola de Fogo preenche, Impacto de Fogo é para quando você se move; Onda de Impacto, Sopro do Dragão e Golpe Flamejante para três ou mais inimigos. Lembretes: Armadura Derretida, Armadura de Mago ou Armadura de Gelo, Combustão abaixo de 20% da vida do alvo, gema de mana, Evocação e os utilitários compartilhados do Mago."
L["rm.tbc.mage.fire.wowhead.Name"] = "Fogo (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Fogo segundo a Wowhead e o simulador. Igual à rotação integrada de Fogo da Icy Veins, mas intercala Impacto de Fogo sempre que estiver pronto enquanto você está parado (mais dano, mais mana) e abre com Bola de Fogo em vez de Ignimpacto. Uma alternativa à rotação integrada de Fogo da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.tbc.mage.frost.Name"] = "Gélido"
L["rm.tbc.mage.frost.Description"] = "Gélido do nível 1 ao 70, e o padrão do Mago antes dos talentos. Seta de Gelo (Bola de Fogo antes do nível 4), Nova Congelante quando algo atinge você, Cone de Frio com Nevasca ou Explosão Arcana quando três ou mais inimigos estão em combate com você, Lança de Gelo em alvos congelados e em movimento, varinha quando a mana acaba. Lembretes: armadura, Inteligência Arcana, gema de mana, Evocação, Contrafeitiço, Roubar Feitiço, Barreira de Gelo, Veias Gélidas, Ruptura do Gelo e Elemental da Água. Lampejo, Bloco de Gelo, kiting e escolha de alvo ficam com você."
